// ==== eventos.js ====
/**
 * Eventos globais — Padrão 2099
 * Utilidades e listeners reutilizáveis.
 */

// Helper: querySelector encurtado
window.$ = (selector, context = document) => context.querySelector(selector);
window.$$ = (selector, context = document) => context.querySelectorAll(selector);

// Delegação de eventos (evita inline onclick)
window.delegar = (elemento, evento, seletor, callback) => {
    elemento.addEventListener(evento, (e) => {
        const alvo = e.target.closest(seletor);
        if (alvo) callback(e, alvo);
    });
};

// ==== theme-toggle.js ====
/**
 * Theme toggle — claro/escuro
 * Persiste escolha do usuário no localStorage.
 */

document.addEventListener('DOMContentLoaded', () => {
    const themeToggle = document.getElementById('theme-toggle');
    if (!themeToggle) return;

    const html = document.documentElement;
    const icon = themeToggle.querySelector('i');

    // 1. Recupera preferência salva OU detecta sistema
    const savedTheme = localStorage.getItem('theme') ||
        (window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');

    // 2. Aplica tema inicial
    html.setAttribute('data-theme', savedTheme);
    atualizarIcone(savedTheme);

    // 3. Listener de clique
    themeToggle.addEventListener('click', () => {
        const atual = html.getAttribute('data-theme');
        const novo = atual === 'dark' ? 'light' : 'dark';

        html.setAttribute('data-theme', novo);
        localStorage.setItem('theme', novo);
        atualizarIcone(novo);
    });

    function atualizarIcone(theme) {
        if (theme === 'dark') {
            icon.className = 'fas fa-sun';
            themeToggle.setAttribute('aria-label', 'Ativar modo claro');
        } else {
            icon.className = 'fas fa-moon';
            themeToggle.setAttribute('aria-label', 'Ativar modo escuro');
        }
    }
});

// ==== menu-hamburger.js ====
/**
 * Menu hamburger — mobile
 * Abre/fecha menu com ARIA correto.
 */

document.addEventListener('DOMContentLoaded', () => {
    const hamburger = document.getElementById('menu-hamburger');
    const menuLinks = document.getElementById('menu-links');
    if (!hamburger || !menuLinks) return;

    hamburger.addEventListener('click', () => {
        const ativo = menuLinks.classList.toggle('active');
        hamburger.setAttribute('aria-expanded', ativo ? 'true' : 'false');
    });

    // Fecha menu ao clicar num link (mobile)
    menuLinks.querySelectorAll('a').forEach((link) => {
        link.addEventListener('click', () => {
            menuLinks.classList.remove('active');
            hamburger.setAttribute('aria-expanded', 'false');
        });
    });
});

